def test_sqlite_store_reconciled_roundtrip() -> None:
    import tempfile
    import os
    tmp = tempfile.mkdtemp()
    db = os.path.join(tmp, "dist.db")
    store = SqliteDistributedStore(db)
    t = _t0()
