@dataclass(frozen=True)
class BehaviorObservation:
    observation_id: str
    entity_id: str
    layer: BehaviorLayer
    action: str
    target: str
    authority: AuthorityState
    environment: EnvironmentState
    score: float                     # 0..1, security-relevant risk/behaviour score
