def _rec(
    rid: str, did: str = "d1", *,
    score: float = 0.9, threshold: float = 0.5,
    truth: bool = True, at: Optional[datetime] = None,
    eid: str = "e1",
) -> DetectionRecord:
    return DetectionRecord(
        record_id=rid, detector_id=did, entity_id=eid,
        score=score, threshold=threshold, truth=truth,
        at=at or _t0(),
    )


