def test_confusion_matrix_expected_cost_empirical() -> None:
    m = ConfusionMatrix(tp=10, fp=10, tn=80, fn=0)
    c = CostMatrix(c_tp=0.1, c_fp=0.3, c_tn=0.0, c_fn=1.0)
