class AdversarialFindingKind(str, Enum):
    INVALID_INTEGRITY_TAG = "invalid_integrity_tag"
    DIGEST_MISMATCH = "digest_mismatch"
    INSUFFICIENT_CORROBORATION = "insufficient_corroboration"
