    g.add_node(_node("b", Layer.NETWORK))
    g.add_node(_node("c", Layer.DATA))
    g.add_edge(_edge("e1", "a", "c",
                     relationship=RelationshipKind.MEDIATES))
    g.add_edge(_edge("e2", "b", "c",
                     relationship=RelationshipKind.MEDIATES))
