def _build_engine() -> AIResilienceEngine:
    eng = AIResilienceEngine()
    for n in _app_graph().nodes():
        eng.add_node(n)
    for e in _app_graph().edges():
        eng.add_edge(e)
    eng.set_residency("app", (SovereignZone.EU,))
    return eng


