    calls = {"n": 0}

    def fail_twice_then_pass() -> None:
        calls["n"] += 1
        if calls["n"] < 2:
            raise TestFailed("first attempt fails")

    eng = CompleteTestingOrchestrator()
    eng.register(_t(
        "t1", runner=fail_twice_then_pass,
        deterministic=False, retries=3,
    ))
    report = eng.run(at=_t0())
    assert report.passed == 1
    assert calls["n"] == 2


