def test_evidence_verified_requires_all() -> None:
    # Missing reviewers
    ok, _ = _evidence_satisfies(
        VerificationStatus.VERIFIED,
        Evidence(
            test_ids=("t1",), passing_runs=1,
            adversarial_results=("a1",),
            wired_into_runtime=True,
        ),
    )
    assert not ok
    # Missing adversarial
    ok, _ = _evidence_satisfies(
        VerificationStatus.VERIFIED,
        Evidence(
            test_ids=("t1",), passing_runs=1,
            independent_reviewers=("r1",),
            wired_into_runtime=True,
        ),
    )
    assert not ok
    # Missing wire
    ok, _ = _evidence_satisfies(
        VerificationStatus.VERIFIED,
        Evidence(
            test_ids=("t1",), passing_runs=1,
            independent_reviewers=("r1",),
            adversarial_results=("a1",),
        ),
    )
    assert not ok
    # All present
    ok, _ = _evidence_satisfies(
        VerificationStatus.VERIFIED,
        Evidence(
            test_ids=("t1",), passing_runs=1,
            independent_reviewers=("r1",),
            adversarial_results=("a1",),
            wired_into_runtime=True,
        ),
    )
    assert ok


